import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum LogType {
  IN = 'ENTRADA',
  OUT = 'SAÍDA'
}

export interface Location {
  latitude: number;
  longitude: number;
  address?: string;
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  department: string;
  photoBase64: string;
  createdAt: number;
}

export interface TimeLog {
  id: string;
  employeeId: string;
  employeeName: string;
  type: LogType;
  timestamp: number;
  location: Location;
  capturedPhoto: string;
  verified: boolean;
  confidence: number;
}

export interface RecognitionResult {
  match: boolean;
  employeeId?: string;
  confidence: number;
  message: string;
}

import { Employee, TimeLog } from '../types';

const KEYS = {
  EMPLOYEES: 'facepoint_employees',
  LOGS: 'facepoint_logs'
};

export const storageService = {
  getEmployees: (): Employee[] => {
    const data = localStorage.getItem(KEYS.EMPLOYEES);
    return data ? JSON.parse(data) : [];
  },

  saveEmployee: (employee: Employee) => {
    const employees = storageService.getEmployees();
    employees.push(employee);
    localStorage.setItem(KEYS.EMPLOYEES, JSON.stringify(employees));
  },

  getLogs: (): TimeLog[] => {
    const data = localStorage.getItem(KEYS.LOGS);
    return data ? JSON.parse(data) : [];
  },

  saveLog: (log: TimeLog) => {
    const logs = storageService.getLogs();
    logs.unshift(log); // Newest first
    localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
  },

  deleteEmployee: (id: string) => {
    const employees = storageService.getEmployees().filter(e => e.id !== id);
    localStorage.setItem(KEYS.EMPLOYEES, JSON.stringify(employees));
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { Employee, RecognitionResult } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  verifyFace: async (capturedImageBase64: string, employees: Employee[]): Promise<RecognitionResult> => {
    if (employees.length === 0) {
      return { match: false, confidence: 0, message: "Nenhum funcionário cadastrado no sistema." };
    }

    // We send the captured image and the gallery of employees to Gemini to find a match
    // For efficiency in this demo, we'll ask Gemini to compare the captured image against the list of profiles.

    const imageParts = [
      {
        inlineData: {
          mimeType: "image/jpeg",
          data: capturedImageBase64.split(',')[1] // Remove data:image/jpeg;base64,
        }
      }
    ];

    // Adding references of employees to the prompt
    // In a real high-scale scenario, we might use a vector DB, but for a standalone demo, 
    // Gemini's multi-modal context is powerful enough for small teams.
    const employeeReferences = employees.map(e => ({
      id: e.id,
      name: e.name,
      photo: e.photoBase64.split(',')[1]
    }));

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            ...imageParts,
            { text: `Você é um sistema de reconhecimento facial de alta precisão. 
              Analise a imagem capturada e compare-a com as fotos de referência dos funcionários abaixo.

              Funcionários Cadastrados:
              ${JSON.stringify(employeeReferences.map(e => ({ id: e.id, name: e.name })))}

              Instruções:
              1. Identifique se a pessoa na imagem capturada é um dos funcionários listados.
              2. Retorne o ID do funcionário se houver um "match" claro (confiança > 0.8).
              3. Se não houver certeza ou a pessoa não estiver na lista, retorne match: false.
              4. Seja rigoroso para evitar fraudes.
            `}
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            match: { type: Type.BOOLEAN },
            employeeId: { type: Type.STRING },
            confidence: { type: Type.NUMBER },
            message: { type: Type.STRING }
          },
          required: ["match", "confidence", "message"]
        }
      }
    });

    try {
      const result = JSON.parse(response.text || '{}');
      return result as RecognitionResult;
    } catch (e) {
      console.error("Erro ao processar resposta do Gemini", e);
      return { match: false, confidence: 0, message: "Erro técnico no reconhecimento." };
    }
  }
};

import React, { useRef, useEffect, useState, useCallback } from 'react';

interface CameraProps {
  onCapture: (base64: string) => void;
  isLoading?: boolean;
}

export const Camera: React.FC<CameraProps> = ({ onCapture, isLoading }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  const startCamera = useCallback(async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: 640, height: 480 },
        audio: false
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
    } catch (err) {
      setError("Não foi possível acessar a câmera. Verifique as permissões.");
      console.error(err);
    }
  }, []);

  useEffect(() => {
    startCamera();
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [startCamera]);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        onCapture(dataUrl);
      }
    }
  };

  return (
    <div className="relative w-full max-w-md mx-auto aspect-video bg-black rounded-2xl overflow-hidden shadow-2xl border-4 border-white">
      {error ? (
        <div className="flex flex-col items-center justify-center h-full p-6 text-center text-white bg-slate-800">
          <i className="fas fa-exclamation-triangle text-4xl mb-4 text-amber-500"></i>
          <p>{error}</p>
          <button 
            onClick={startCamera}
            className="mt-4 px-4 py-2 bg-indigo-600 rounded-lg hover:bg-indigo-700 transition"
          >
            Tentar Novamente
          </button>
        </div>
      ) : (
        <>
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            className="w-full h-full object-cover scale-x-[-1]" 
          />
          <canvas ref={canvasRef} className="hidden" />

          <div className="absolute inset-0 pointer-events-none border-[40px] border-black/20">
             <div className="w-full h-full border-2 border-dashed border-white/50 rounded-full opacity-30"></div>
          </div>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2">
            <button
              onClick={capture}
              disabled={isLoading}
              className={`w-16 h-16 rounded-full border-4 border-white flex items-center justify-center transition-all ${
                isLoading ? 'bg-slate-400 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'
              }`}
            >
              {isLoading ? (
                <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <div className="w-10 h-10 bg-white rounded-full opacity-50"></div>
              )}
            </button>
          </div>

          {isLoading && (
            <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
              <div className="bg-white/90 backdrop-blur px-6 py-3 rounded-full shadow-lg flex items-center gap-3">
                <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                <span className="font-medium text-indigo-900">Validando biometria...</span>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Camera } from './components/Camera';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import { Employee, TimeLog, LogType, Location } from './types';

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'register' | 'admin'>('dashboard');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [logs, setLogs] = useState<TimeLog[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error', msg: string } | null>(null);

  // Form states for new employee
  const [newEmployeeName, setNewEmployeeName] = useState('');
  const [newEmployeeRole, setNewEmployeeRole] = useState('');
  const [capturedNewPhoto, setCapturedNewPhoto] = useState<string | null>(null);

  useEffect(() => {
    setEmployees(storageService.getEmployees());
    setLogs(storageService.getLogs());
  }, []);

  const clearFeedback = () => setTimeout(() => setFeedback(null), 5000);

  const getCurrentLocation = (): Promise<Location> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve({ latitude: 0, longitude: 0 });
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (pos) => resolve({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        () => resolve({ latitude: 0, longitude: 0 })
      );
    });
  };

  const handlePointRegistration = async (photo: string) => {
    setIsProcessing(true);
    try {
      const location = await getCurrentLocation();
      const result = await geminiService.verifyFace(photo, employees);

      if (result.match && result.employeeId) {
        const employee = employees.find(e => e.id === result.employeeId);
        if (employee) {
          // Determine if it's an Entry or Exit based on last log
          const lastLog = logs.find(l => l.employeeId === employee.id);
          const type = (!lastLog || lastLog.type === LogType.OUT) ? LogType.IN : LogType.OUT;

          const newLog: TimeLog = {
            id: crypto.randomUUID(),
            employeeId: employee.id,
            employeeName: employee.name,
            type,
            timestamp: Date.now(),
            location,
            capturedPhoto: photo,
            verified: true,
            confidence: result.confidence
          };

          storageService.saveLog(newLog);
          setLogs(prev => [newLog, ...prev]);
          setFeedback({ type: 'success', msg: `Ponto de ${type} registrado: ${employee.name}` });
          setView('dashboard');
        }
      } else {
        setFeedback({ type: 'error', msg: result.message || "Rosto não reconhecido. Tente novamente." });
      }
    } catch (err) {
      console.error(err);
      setFeedback({ type: 'error', msg: "Ocorreu um erro ao processar o registro." });
    } finally {
      setIsProcessing(false);
      clearFeedback();
    }
  };

  const handleCreateEmployee = () => {
    if (!newEmployeeName || !newEmployeeRole || !capturedNewPhoto) {
      setFeedback({ type: 'error', msg: "Preencha todos os campos e capture a foto." });
      return;
    }

    const newEmp: Employee = {
      id: crypto.randomUUID(),
      name: newEmployeeName,
      role: newEmployeeRole,
      department: 'Geral',
      photoBase64: capturedNewPhoto,
      createdAt: Date.now()
    };

    storageService.saveEmployee(newEmp);
    setEmployees(prev => [...prev, newEmp]);
    setFeedback({ type: 'success', msg: "Funcionário cadastrado com sucesso!" });
    setNewEmployeeName('');
    setNewEmployeeRole('');
    setCapturedNewPhoto(null);
    setView('admin');
    clearFeedback();
  };

  return (
    <div className="flex h-full bg-slate-50 font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-indigo-900 text-white flex flex-col shadow-xl z-20">
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-500 rounded-lg flex items-center justify-center">
            <i className="fas fa-fingerprint text-xl"></i>
          </div>
          <span className="text-xl font-bold tracking-tight">FacePoint</span>
        </div>

        <nav className="flex-1 mt-4 px-4 space-y-2">
          <button 
            onClick={() => setView('dashboard')}
            className={`w-full text-left px-4 py-3 rounded-xl transition flex items-center gap-3 ${view === 'dashboard' ? 'bg-indigo-800' : 'hover:bg-indigo-800/50'}`}
          >
            <i className="fas fa-chart-line w-5"></i> Dashboard
          </button>
          <button 
            onClick={() => setView('register')}
            className={`w-full text-left px-4 py-3 rounded-xl transition flex items-center gap-3 ${view === 'register' ? 'bg-indigo-800' : 'hover:bg-indigo-800/50'}`}
          >
            <i className="fas fa-camera w-5"></i> Registrar Ponto
          </button>
          <button 
            onClick={() => setView('admin')}
            className={`w-full text-left px-4 py-3 rounded-xl transition flex items-center gap-3 ${view === 'admin' ? 'bg-indigo-800' : 'hover:bg-indigo-800/50'}`}
          >
            <i className="fas fa-users-cog w-5"></i> Gestão
          </button>
        </nav>

        <div className="p-4 bg-indigo-950/50 text-xs text-indigo-300">
          Powered by Gemini AI 3.0
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 px-8 flex items-center justify-between shadow-sm">
          <h1 className="text-lg font-semibold text-slate-700">
            {view === 'dashboard' && 'Painel de Controle'}
            {view === 'register' && 'Registro Biométrico'}
            {view === 'admin' && 'Administração de Funcionários'}
          </h1>
          <div className="flex items-center gap-4">
             <div className="text-right">
               <div className="text-sm font-medium text-slate-900">{new Date().toLocaleDateString('pt-BR')}</div>
               <div className="text-xs text-slate-500">Sistema Online</div>
             </div>
             <div className="w-10 h-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 border border-slate-300">
               <i className="fas fa-user"></i>
             </div>
          </div>
        </header>

        {/* Feedback Toast */}
        {feedback && (
          <div className={`fixed top-20 right-8 z-50 animate-bounce px-6 py-4 rounded-xl shadow-2xl flex items-center gap-4 ${
            feedback.type === 'success' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'
          }`}>
            <i className={`fas ${feedback.type === 'success' ? 'fa-check-circle' : 'fa-exclamation-circle'}`}></i>
            <span className="font-medium">{feedback.msg}</span>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-8">

          {/* Dashboard View */}
          {view === 'dashboard' && (
            <div className="max-w-6xl mx-auto space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                  <div className="flex items-center gap-4 mb-4 text-indigo-600">
                    <i className="fas fa-users text-2xl"></i>
                    <h3 className="font-semibold">Total de Funcionários</h3>
                  </div>
                  <p className="text-3xl font-bold text-slate-800">{employees.length}</p>
                </div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                  <div className="flex items-center gap-4 mb-4 text-emerald-600">
                    <i className="fas fa-clock text-2xl"></i>
                    <h3 className="font-semibold">Registros Hoje</h3>
                  </div>
                  <p className="text-3xl font-bold text-slate-800">
                    {logs.filter(l => new Date(l.timestamp).toDateString() === new Date().toDateString()).length}
                  </p>
                </div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                  <div className="flex items-center gap-4 mb-4 text-amber-600">
                    <i className="fas fa-shield-alt text-2xl"></i>
                    <h3 className="font-semibold">Status de Segurança</h3>
                  </div>
                  <p className="text-3xl font-bold text-slate-800">Ativo</p>
                </div>
              </div>

              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800">Logs Recentes</h3>
                  <button className="text-indigo-600 text-sm font-medium hover:underline">Ver Histórico Completo</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
                      <tr>
                        <th className="px-6 py-4 text-left">Funcionário</th>
                        <th className="px-6 py-4 text-left">Tipo</th>
                        <th className="px-6 py-4 text-left">Horário</th>
                        <th className="px-6 py-4 text-left">Localização</th>
                        <th className="px-6 py-4 text-left">Verificação AI</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {logs.length === 0 ? (
                        <tr>
                          <td colSpan={5} className="px-6 py-10 text-center text-slate-400">Nenhum registro encontrado.</td>
                        </tr>
                      ) : (
                        logs.map(log => (
                          <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-4">
                              <div className="flex items-center gap-3">
                                <img src={log.capturedPhoto} className="w-8 h-8 rounded-full object-cover border border-slate-200" alt="" />
                                <span className="font-medium text-slate-800">{log.employeeName}</span>
                              </div>
                            </td>
                            <td className="px-6 py-4">
                              <span className={`px-2 py-1 rounded-full text-[10px] font-bold ${
                                log.type === LogType.IN ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                              }`}>
                                {log.type}
                              </span>
                            </td>
                            <td className="px-6 py-4 text-slate-600 text-sm">
                              {new Date(log.timestamp).toLocaleString('pt-BR')}
                            </td>
                            <td className="px-6 py-4 text-slate-500 text-xs">
                              {log.location.latitude.toFixed(4)}, {log.location.longitude.toFixed(4)}
                            </td>
                            <td className="px-6 py-4">
                              <div className="flex items-center gap-2">
                                <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                                <span className="text-xs text-slate-600">{(log.confidence * 100).toFixed(0)}% confiança</span>
                              </div>
                            </td>
                          </tr>
                        ))
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}

          {/* Register Point View */}
          {view === 'register' && (
            <div className="max-w-2xl mx-auto flex flex-col items-center">
              <div className="text-center mb-8">
                <h2 className="text-3xl font-bold text-slate-800 mb-2">Ponto Facial</h2>
                <p className="text-slate-500">Posicione seu rosto dentro do círculo para identificação automática.</p>
              </div>

              <Camera 
                onCapture={handlePointRegistration} 
                isLoading={isProcessing} 
              />

              <div className="mt-8 bg-indigo-50 p-6 rounded-2xl border border-indigo-100 text-indigo-800 flex items-start gap-4">
                <i className="fas fa-info-circle mt-1"></i>
                <div>
                  <h4 className="font-bold mb-1 text-sm">Dicas de Uso:</h4>
                  <ul className="text-xs space-y-1 opacity-80 list-disc list-inside">
                    <li>Garanta que o ambiente esteja bem iluminado</li>
                    <li>Mantenha o rosto centralizado no visor</li>
                    <li>Evite acessórios que cubram muito o rosto (óculos escuros, máscaras)</li>
                  </ul>
                </div>
              </div>
            </div>
          )}

          {/* Admin / Management View */}
          {view === 'admin' && (
            <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8">

              {/* Form to add employee */}
              <div className="lg:col-span-1">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                  <h3 className="text-xl font-bold text-slate-800 mb-6">Novo Cadastro</h3>

                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-600 mb-1">Nome Completo</label>
                      <input 
                        type="text" 
                        value={newEmployeeName}
                        onChange={(e) => setNewEmployeeName(e.target.value)}
                        className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition"
                        placeholder="Ex: João da Silva"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-600 mb-1">Cargo</label>
                      <input 
                        type="text" 
                        value={newEmployeeRole}
                        onChange={(e) => setNewEmployeeRole(e.target.value)}
                        className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition"
                        placeholder="Ex: Desenvolvedor Senior"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-slate-600 mb-2">Foto de Referência (Biometria)</label>
                      {capturedNewPhoto ? (
                        <div className="relative group">
                          <img src={capturedNewPhoto} className="w-full h-48 object-cover rounded-xl border-2 border-indigo-500" alt="Reference" />
                          <button 
                            onClick={() => setCapturedNewPhoto(null)}
                            className="absolute top-2 right-2 w-8 h-8 bg-rose-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition shadow-lg"
                          >
                            <i className="fas fa-times"></i>
                          </button>
                        </div>
                      ) : (
                        <div className="h-48 rounded-xl border-2 border-dashed border-slate-200 bg-slate-50 flex flex-col items-center justify-center text-slate-400 group overflow-hidden">
                           <Camera onCapture={(photo) => setCapturedNewPhoto(photo)} />
                        </div>
                      )}
                    </div>

                    <button 
                      onClick={handleCreateEmployee}
                      className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200"
                    >
                      Cadastrar Funcionário
                    </button>
                  </div>
                </div>
              </div>

              {/* Employee List */}
              <div className="lg:col-span-2">
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                  <div className="p-6 border-b border-slate-100">
                    <h3 className="font-bold text-slate-800">Funcionários Ativos</h3>
                  </div>
                  <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
                    {employees.length === 0 ? (
                      <div className="col-span-2 py-20 text-center">
                        <i className="fas fa-user-slash text-4xl text-slate-200 mb-4"></i>
                        <p className="text-slate-400">Nenhum funcionário cadastrado ainda.</p>
                      </div>
                    ) : (
                      employees.map(emp => (
                        <div key={emp.id} className="group relative bg-slate-50 p-4 rounded-xl border border-slate-100 flex items-center gap-4 hover:border-indigo-200 hover:bg-indigo-50/30 transition">
                          <img src={emp.photoBase64} className="w-16 h-16 rounded-lg object-cover border border-white shadow-sm" alt="" />
                          <div className="flex-1 min-w-0">
                            <h4 className="font-bold text-slate-800 truncate">{emp.name}</h4>
                            <p className="text-xs text-slate-500 truncate">{emp.role}</p>
                            <span className="text-[10px] text-indigo-400 uppercase font-bold tracking-wider">{emp.department}</span>
                          </div>
                          <button 
                            onClick={() => {
                              storageService.deleteEmployee(emp.id);
                              setEmployees(prev => prev.filter(e => e.id !== emp.id));
                            }}
                            className="w-8 h-8 rounded-full bg-white text-slate-300 hover:text-rose-500 hover:bg-rose-50 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100"
                          >
                            <i className="fas fa-trash-alt text-xs"></i>
                          </button>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>

            </div>
          )}

        </div>
      </main>
    </div>
  );
};

export default App;
